"""
Politically Exposed Persons (PEP) Comprehensive Institutional Registry.
Covers Tier 1, Tier 2, and Tier 3 PEPs, Relatives & Close Associates (RCA), and High-Profile Officials.
"""

from dataclasses import dataclass, field
from typing import List, Dict, Optional, Any, Set
import re

@dataclass
class PEPEntry:
    pep_id: str
    full_name: str
    country_code: str
    country_name: str
    region: str
    tier: int  # 1, 2, or 3
    role_title: str
    department_or_agency: str
    term_start: str
    term_end: Optional[str] = None
    is_active: bool = True
    inherent_risk_rating: str = "HIGH"  # CRITICAL, HIGH, MEDIUM-HIGH
    risk_score: float = 8.5
    associated_entities: List[str] = field(default_factory=list)
    relatives_and_associates: List[Dict[str, str]] = field(default_factory=list)
    source_of_wealth: Optional[str] = None
    adverse_media_count: int = 0
    aliases: List[str] = field(default_factory=list)

